def move_one_ball(arr):
    if not arr:
        return True

    # A sorted array that is cyclically shifted will have at most one 
    # point where arr[i] > arr[i+1].
    # We check the adjacent pairs, including the wrap-around pair (last, first).

    drops = 0
    n = len(arr)

    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1

    return drops <= 1

