def max_fill(grid, capacity):
    """
    Calculates the number of times buckets need to be lowered to empty all wells.
    Uses recursion to process rows and calculate bucket requirements.
    """

    def count_ones(row):
        """Recursively counts the number of 1s in a list."""
        if not row:
            return 0
        return (1 if row[0] == 1 else 0) + count_ones(row[1:])

    def calculate_total_lowers(rows):
        """Recursively processes rows to sum the required bucket lowers."""
        if not rows:
            return 0

        water_in_row = count_ones(rows[0])
        lowers_for_row = math.ceil(water_in_row / capacity)

        return lowers_for_row + calculate_total_lowers(rows[1:])

    return calculate_total_lowers(grid)

