def get_odd_collatz(n: int) -> list[int]:
    """
    Given a positive integer n, return a sorted list of the odd numbers in its Collatz sequence.

    Args:
        n: A positive integer.

    Returns:
        A sorted list containing the odd numbers encountered in the Collatz sequence starting from n.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    odd_numbers = set()
    current_number = n

    while current_number != 1:
        if current_number % 2 != 0:
            odd_numbers.add(current_number)

        if current_number % 2 == 0:
            current_number //= 2
        else:
            current_number = 3 * current_number + 1

    odd_numbers.add(1)  # The sequence always ends with 1, which is odd.

    return sorted(list(odd_numbers))
